// Title: Insert PdfBookmarkEntry into Workbook.PdfBookmarks Before Saving PDF with Aspose.Cells for .NET
// Description: Demonstrates how to add a root PdfBookmarkEntry (with nested sub‑entries) to the Workbook.PdfBookmarks collection so that the bookmark hierarchy appears in the PDF generated by Aspose.Cells. The example creates a three‑sheet workbook, defines cell destinations, builds the bookmark tree, registers it with the workbook, and saves the file as a PDF.
// Keywords: Aspose.Cells PDF bookmarks | PdfBookmarkEntry C# | Workbook.PdfBookmarks usage | export Excel to PDF with bookmarks | .NET Aspose.Cells example | hierarchical PDF bookmark tree | add PDF bookmark before save | Aspose.Cells PdfSaveOptions Bookmark
// Common Searches: how to add pdf bookmarks in Aspose.Cells | PdfBookmarkEntry not showing in exported PDF | C# Aspose.Cells add root bookmark to workbook | save workbook as PDF with table of contents | Aspose.Cells PdfBookmarks collection example
// Developer Intent: Add the constructed PdfBookmarkEntry hierarchy to the workbook's PdfBookmarks collection so the bookmarks are embedded in the exported PDF.
// Use Cases: Generate a PDF report with a clickable table of contents that links to specific worksheets. | Provide end‑users with navigation shortcuts inside PDFs created from multi‑sheet Excel workbooks. | Automate creation of PDF documentation where each section corresponds to a cell range in the source workbook.
// AI Prompts: Write C# code that creates a PdfBookmarkEntry hierarchy and registers it with Workbook.PdfBookmarks before calling Workbook.Save with PdfSaveOptions. | Show how to build nested PDF bookmarks for a multi‑sheet workbook using Aspose.Cells for .NET and ensure they appear in the saved PDF. | Provide an example that adds multiple PdfBookmarkEntry objects to the PdfBookmarks collection, sets IsOpen, and exports the workbook to PDF with those bookmarks.

using System;
using System.Collections;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// Demonstrates how to add a root PdfBookmarkEntry (with nested sub‑entries) to the Workbook.PdfBookmarks collection so that the bookmark hierarchy appears in the PDF generated by Aspose.Cells. The example creates a three‑sheet workbook, defines cell destinations, builds the bookmark tree, registers it with the workbook, and saves the file as a PDF.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add three worksheets
            Workbook workbook = new Workbook();
            workbook.Worksheets.Add(); // Sheet2
            workbook.Worksheets.Add(); // Sheet3

            // Define cells that will serve as bookmark destinations
            Cell cellPage1 = workbook.Worksheets[0].Cells["A1"];
            Cell cellPage2 = workbook.Worksheets[1].Cells["A1"];
            Cell cellPage3 = workbook.Worksheets[2].Cells["A1"];

            cellPage1.PutValue("Page 1 Content");
            cellPage2.PutValue("Page 2 Content");
            cellPage3.PutValue("Page 3 Content");

            // Create the root PDF bookmark entry
            PdfBookmarkEntry rootBookmark = new PdfBookmarkEntry
            {
                Text = "Root",
                Destination = cellPage1,
                SubEntry = new ArrayList(),
                IsOpen = true
            };

            // Create sub‑bookmarks
            PdfBookmarkEntry subBookmark1 = new PdfBookmarkEntry
            {
                Text = "Section 1",
                Destination = cellPage2
            };

            PdfBookmarkEntry subBookmark2 = new PdfBookmarkEntry
            {
                Text = "Section 2",
                Destination = cellPage3
            };

            // Assemble the hierarchy
            rootBookmark.SubEntry.Add(subBookmark1);
            rootBookmark.SubEntry.Add(subBookmark2);

            // Configure PDF save options and assign the root bookmark
            PdfSaveOptions pdfOptions = new PdfSaveOptions
            {
                Bookmark = rootBookmark
            };

            // Save the workbook as a PDF
            workbook.Save("output.pdf", pdfOptions);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
